-- Plain-language help mirrors permission-help.json; this changes presentation only.
-- V999_11 落库的六个 finance_application 码当时只有一句话用途；按 V983/V1001 的同一
-- 受控模式把名称与说明对齐唯一说明目录(permission-help.json)。仅改 name/description：
-- action_type、grant_policy、baseline、high_risk、授权行与页面权限面全部保持原样；
-- finance_application:reverse 的名称同时去掉契约测试禁用的「反审」措辞。
UPDATE permissions p SET name=h.name,description=h.description FROM (VALUES
 ('finance_application:apply','填写付款及预付申请',E'能做什么：填写工资发放之外的付款、预付等支付前申请，登记用途和相应依据。\n\n范围与限制：仅填写真实支付前申请，不会因此扣款或生成费用；审批、登记实际付款和财务确认仍须各自授权，填写不自动获得这些权限。\n\n提醒和待办：按本人申请和当前已授权且可办理的节点显示待办，已处理、撤回和驳回后同步数量。\n\n例如：经办人填写某项付款申请并附上依据，提交后等待部门、财务或总经办节点审批。'),
 ('finance_application:confirm','财务确认申请付款分录',E'能做什么：确认申请付款对应的既有实际付款和凭证，完成申请侧财务确认。\n\n范围与限制：确认既有实际付款和凭证，不会重新计薪、计费用或扣款；反审付款须另行授权并沿原依赖执行。\n\n提醒和待办：待确认的申请付款分录计入财务待办，确认后关闭。\n\n例如：财务核对本申请登记的付款与凭证一致后确认，申请流程办结。'),
 ('finance_application:execute','登记已批准申请的实际付款',E'能做什么：为已批准的申请按真实银行回单登记实际付款日期、流水号和凭据。\n\n范围与限制：批准支付之后按真实回单登记付款，仍要求原付款、费用或工资执行资格，不能重复支付，也不因此获得审批或财务确认权限。\n\n提醒和待办：仅当前可由本人办理付款的已批准申请计入待办，登记后待办关闭。\n\n例如：出纳凭银行回单为已批准的申请登记实际付款，保留回单凭据。'),
 ('finance_application:reverse','撤销申请的实际付款登记',E'能做什么：按原付款依赖和账期保护对称撤销已登记的申请实际付款。\n\n范围与限制：沿原付款依赖和账期保护对称撤销，保留原申请、节点和回执历史；不改动已确认的财务凭证事实。\n\n提醒和待办：仅本人登记且仍可撤销的付款进入可办理范围，撤销后相关待办重新出现。\n\n例如：登记错付款后，沿原依赖撤销该笔付款登记并保留完整历史。'),
 ('finance_application:review','办理指派的申请节点',E'能做什么：办理本单当前明确指派给本人的部门、财务或总经办审核节点，填写通过或驳回原因。\n\n范围与限制：只办理本单当前明确指派的部门、财务或总经办节点，不能越级或审批本人申请，也不因此获得付款登记或财务确认权限。\n\n提醒和待办：只有轮到本人办理的节点计入待办，已处理节点不再重复提醒。\n\n例如：财务初核人核对申请金额与依据后通过，单据流向下一节点。'),
 ('finance_application:view','查看各部门申请流程',E'能做什么：查看本人发起、明确指派给本人办理或本人已处理的各部门申请流程、节点进度和回执。\n\n范围与限制：只增加本项说明的查看能力，不因此开放全部员工薪资和公司报销，也不能修改、审批或代办；他人申请数据仍需相应范围，敏感金额与附件继续单独检查权限。\n\n提醒和待办：仅查看不会把你加入该业务的待办，不显示红黄任务徽章，也不因此收到该业务办理通知。\n\n例如：部门负责人查看指派给本部门的申请当前走到哪个节点；不能据此查看全部员工薪资和公司报销。')
) h(code,name,description) WHERE p.code=h.code;
